/**
 * Recipe to change the casing of AWS SDK for Java v1 enum constants to the v2 convention. v1 enum constants use Pascal case
 * (e.g. {@code RouteType.Transactional}) while v2 enum constants use screaming snake case (e.g. {@code RouteType.TRANSACTIONAL}).
 */
@SdkInternalApi
public class EnumCasingToV2 extends Recipe {

    @Override
    public String getDisplayName() {
        return "Change the casing of v1 enum constants to v2";
    }

    @Override
    public String getDescription() {
        return "v1 enum constants are Pascal case while v2 enum constants are screaming snake case, e.g., v1: "
               + "RouteType.Transactional, v2: RouteType.TRANSACTIONAL.";
    }

    @Override
    public TreeVisitor<?, ExecutionContext> getVisitor() {
        return new EnumCasingVisitor();
