    private static final class EnumCasingVisitor extends JavaVisitor<ExecutionContext> {

        @Override
        public J visitFieldAccess(J.FieldAccess fieldAccess, ExecutionContext ctx) {
            J.FieldAccess fa = (J.FieldAccess) super.visitFieldAccess(fieldAccess, ctx);

            if (!isSdkModelEnumConstant(fa)) {
                return fa;
            }

            String currentName = fa.getName().getSimpleName();
            String v2Name = screamingSnakeCase(currentName);
            if (v2Name.equals(currentName)) {
                return fa;
            }

            return fa.withName(fa.getName().withSimpleName(v2Name));
        }

        private static boolean isSdkModelEnumConstant(J.FieldAccess fieldAccess) {
            JavaType targetType = fieldAccess.getTarget().getType();
            JavaType.FullyQualified fullyQualified = TypeUtils.asFullyQualified(targetType);
            if (fullyQualified == null) {
                return false;
            }

            if (!isV1ModelClass(fullyQualified) && !isV2ModelClass(fullyQualified)) {
                return false;
            }

            // An enum constant is a static field whose type is the enclosing enum itself (e.g. RouteType.Transactional),
            // which distinguishes it from other member accesses such as RouteType.class.
            return TypeUtils.isOfType(fieldAccess.getName().getType(), targetType);
        }

        private static String screamingSnakeCase(String name) {
            return Stream.of(CodegenNamingUtils.splitOnWordBoundaries(name))
                         .map(word -> word.toUpperCase(Locale.US))
                         .collect(Collectors.joining("_"));
